+    margin: 0 0 0.5rem;
+    color: #ffc107;
+    font-size: 1.1rem;
+}
+
+.badge-out-of-stock {
+    display: inline-block;
+    padding: 0.2rem 0.5rem;
+    background: #dc3545;
+    color: white;
+    border-radius: 4px;
+    font-size: 0.75rem;
+    margin-bottom: 0.5rem;
+}
+
+.btn-add-to-cart {
+    width: 100%;
+    padding: 0.5rem;
+    border: none;
+    border-radius: 4px;
+    background: #0d6efd;
+    color: white;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.btn-add-to-cart:hover:not(:disabled) {
+    background: #0b5ed7;
+}
+
+.btn-add-to-cart:disabled {
+    background: #adb5bd;
+    cursor: not-allowed;
+}
+
+/* Pagination */
+.catalog-pagination {
+    display: flex;
+    justify-content: center;
+    align-items: center;
+    gap: 0.4rem;
+    margin-top: 1.5rem;
+    padding: 1rem 0;
+}
+
+.btn-page {
+    padding: 0.4rem 0.75rem;
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    background: white;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+.btn-page:hover:not(:disabled):not(.active) {
+    background: #e9ecef;
+}
+
+.btn-page.active {
+    background: #0d6efd;
+    color: white;
+    border-color: #0d6efd;
+}
+
+.btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* States */
+.catalog-loading,
+.catalog-empty,
+.catalog-error {
+    padding: 3rem;
+    text-align: center;
+    color: #6c757d;
+}
+
+.catalog-error {
+    color: #dc3545;
+}
+
+.catalog-error button {
+    margin-top: 1rem;
+    padding: 0.5rem 1.5rem;
+    border: none;
+    border-radius: 4px;
+    background: #0d6efd;
+    color: white;
+    cursor: pointer;
+}
+

